const events = $input.first().json.events;
if (!Array.isArray(events) || events.length === 0) return [];

return events.map((event) => ({
  json: {
    id: event.id,
    userId: event.userId,
  },
}));

const rows = $input.all().map((item) => item.json ?? {});
const byClassification = {};
const routing = { rule: 0, ai: 0, other: 0 };
let openAiTokens = 0;
let held = 0;
let failed = 0;
const attentionClasses = new Set(['APPLICATION_RECEIVED', 'RECRUITER_OUTREACH', 'INTERVIEW', 'TEST_TASK', 'OFFER', 'OTHER']);
const attention = [];

for (const row of rows) {
  const classification = String(row.classification ?? 'UNKNOWN');
  byClassification[classification] = (byClassification[classification] ?? 0) + 1;

  const source = String(row.source ?? '');
  if (source.startsWith('RULE:')) routing.rule += 1;
  else if (source.startsWith('OPENAI:')) routing.ai += 1;
  else routing.other += 1;

  const processingStatus = String(row.processingStatus ?? '');
  if (processingStatus === 'HOLD') held += 1;
  if (processingStatus === 'FAILED') failed += 1;

  openAiTokens += Number(row.aiUsage?.totalTokens ?? 0);

  if (attentionClasses.has(classification) && row.action !== 'NO_ACTION') {
    attention.push({
      id: row.id ?? null,
      classification,
      company: row.company ?? null,
      jobTitle: row.jobTitle ?? null,
      action: row.action ?? null,
      summary: row.summary ?? null,
    });
  }
}

const status = failed > 0 ? 'COMPLETED_WITH_ERRORS' : held > 0 ? 'COMPLETED_WITH_HOLD' : 'COMPLETED';
const message = `Batch complete: ${rows.length} processed, ${routing.rule} by rules, ${routing.ai} by AI, ${held} held, ${failed} failed.`;

return [{
  json: {
    status,
    message,
    completedAt: new Date().toISOString(),
    processed: rows.length,
    byClassification,
    routing,
    openAiTokens,
    held,
    failed,
    needsAttention: attention.length,
    attention: attention.slice(0, 10),
  },
}];
